<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_role('admin');$kid=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM kegiatan WHERE id_kegiatan=?');$q->execute([$kid]);$k=$q->fetch();if(!$k||!in_array($k['tujuan_akhir'],['lpd','keduanya'],true)){http_response_code(404);exit('Modul LPD tidak tersedia.');}
$ps=$pdo->prepare('SELECT id_petugas,nama_petugas,kecamatan FROM petugas WHERE id_kegiatan=? ORDER BY nama_petugas');$ps->execute([$kid]);$staff=$ps->fetchAll();$qs=$pdo->prepare("SELECT ph.id_progress,ph.id_petugas,ph.tanggal,COUNT(dp.id_detail) jumlah_detail,SUM(CASE WHEN dp.uraian_kegiatan IS NULL OR TRIM(dp.uraian_kegiatan)='' OR dp.output_tujuan IS NULL OR TRIM(dp.output_tujuan)='' THEN 1 ELSE 0 END) incomplete FROM progress_harian ph LEFT JOIN detail_progress dp ON dp.id_progress=ph.id_progress WHERE ph.id_kegiatan=? GROUP BY ph.id_progress,ph.id_petugas,ph.tanggal");$qs->execute([$kid]);$map=[];foreach($qs->fetchAll() as $r)$map[$r['id_petugas'].'|'.$r['tanggal']]=$r;
$dates=[];$start=new DateTimeImmutable($k['tanggal_mulai']);$end=new DateTimeImmutable($k['tanggal_selesai']);for($d=$start;$d<=$end;$d=$d->modify('+1 day'))$dates[]=$d->format('Y-m-d');$rows=[];foreach($dates as $date)foreach($staff as $p){$r=$map[$p['id_petugas'].'|'.$date]??null;$rows[]=['tanggal'=>$date,'petugas'=>$p,'progress'=>$r];}
page_header('Monitoring LPD');?><div class="card p-4 mb-3"><div class="d-flex justify-content-between"><div><h2 class="h5 fw-bold"><?=e($k['nama_kegiatan'])?></h2><div class="text-secondary small"><?=e($k['nomor_kegiatan'])?> · <?=format_tanggal($k['tanggal_mulai'])?> – <?=format_tanggal($k['tanggal_selesai'])?></div></div><a class="btn btn-light" href="<?=APP_BASE_URL?>/admin/kegiatan/detail.php?id=<?=$kid?>">Kembali</a></div></div><div class="card p-4"><h3 class="h5 fw-bold">Daftar LPD per Petugas dan Tanggal</h3><p class="small text-secondary">Daftar menampilkan seluruh kombinasi tanggal periode dan identitas petugas. PDF hanya dapat diunduh jika detail LPD sudah lengkap.</p><div class="table-responsive"><table class="table"><thead><tr><th>No</th><th>Tanggal</th><th>Nama Petugas</th><th>Kecamatan</th><th>Detail SLS</th><th>Status LPD</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $i=>$r):$x=$r['progress'];$ready=$x&&(int)$x['jumlah_detail']>0&&(int)($x['incomplete']??0)===0;?><tr><td><?=$i+1?></td><td><?=format_tanggal($r['tanggal'])?></td><td><?=e($r['petugas']['nama_petugas'])?></td><td><?=e($r['petugas']['kecamatan'])?></td><td><?=$x?(int)$x['jumlah_detail']:0?></td><td><span class="badge text-bg-<?=$ready?'success':'secondary'?>"><?=$ready?'Sudah tersedia':($x?'Belum lengkap':'Belum dibuat')?></span></td><td><?php if($ready):?><a class="btn btn-sm btn-outline-primary" href="<?=APP_BASE_URL?>/admin/lpd/download.php?progress_id=<?=$x['id_progress']?>">Download PDF</a><?php else:?>-<?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="text-center text-secondary py-4">Belum ada petugas pada kegiatan ini.</td></tr><?php endif;?></tbody></table></div></div><?php page_footer();
